const telefon = { marka: "Samsung", model: "S24", cena: 3500 };
telefon.cena = 2999;
telefon.kolor = "czarny";
console.log(telefon);
// { marka: 'Samsung', model: 'S24', cena: 2999, kolor: 'czarny' }

const film = { tytul: "Incepcja", gatunek: "sci-fi" };
delete film.gatunek;
console.log(film); // { tytul: 'Incepcja' } - gatunek CALKOWICIE usuniety

const osoba = {
  imie: "Kasia",
  przedstawSie() {
    return `Czesc, jestem ${this.imie}`;
  }
};

console.log(osoba.przedstawSie()); // "Czesc, jestem Kasia"

const ksiazka = { tytul: "Diuna", autor: "Frank Herbert" };
const pole = "autor";
console.log(ksiazka[pole]); // "Frank Herbert"

const nazwaKlucza = "kolor";
const obiekt = { [nazwaKlucza]: "czerwony" };
console.log(obiekt); // { kolor: 'czerwony' }

const prefix = "produkt";
const obiekt = {
  [`${prefix}Id`]: 42,
  [`${prefix}Nazwa`]: "Laptop"
};
console.log(obiekt); // { produktId: 42, produktNazwa: 'Laptop' }

const marka = "Toyota";
const model = "Corolla";
const auto = { marka, model };
console.log(auto); // { marka: 'Toyota', model: 'Corolla' }

function stworzUzytkownika(imie, wiek) {
  return { imie, wiek };
}

console.log(stworzUzytkownika("Ala", 25)); // { imie: 'Ala', wiek: 25 }
